"齔":"龀齔","龁":"龁齕","齕":"龁齕","龂":"龂齗","齗":"龂齗","𬹼":"𬹼齘","齘":"𬹼齘","龅":"龅齙","齙":"龅齙","龇":"龇齜","齜":"龇齜","龃":"龃齟","齟":"龃齟","龆":"龆齠","齠":"龆齠","龄":"龄齡","齡":"龄齡","出":"出齣","齣":"出齣","龈":"龈齦","齦":"龈齦","𫜪":"𫜪齩","齩":"𫜪齩","龊":"龊齪","齪":"龊齪","龉":"龉齬","齬":"龉齬","𫜭":"𫜭齭","齭":"𫜭齭","𬺈":"𬺈齮","齮":"𬺈齮","𫠜":"𫠜齯","齯":"𫠜齯","𫜬":"𫜬齰","齰":"𫜬齰","龋":"龋齲","齲":"龋齲","𫜮":"𫜮齴","齴":"𫜮齴","腭":"腭齶","齶":"腭齶","龌":"龌齷","齷":"龌齷","𬺓":"𬺓齼","齼":"𬺓齼","𫜰":"𫜰齾","齾":"𫜰齾","龙":"龙龍","龍":"龙龍","厐":"厐龎","龎":"厐龎","庞":"庞龐","龐":"庞龐","䶮":"䶮龑","龑":"䶮龑","𫜲":"𫜲龓","龓":"𫜲龓","龚":"龚龔","龔":"龚龔","龛":"龛龕","龕":"龛龕","龟":"龟龜","龜":"龟龜","𩨎":"𩨎龭","龭":"𩨎龭","𨱆":"𨱆龯","龯":"𨱆龯","䜤":"䜤鿁","鿁":"䜤鿁","鿒":"鿒鿓","鿓":"鿒鿓"}'::jsonb;
  res text := '';
  ch text; cls text;
begin
  if q is null or q = '' then return null; end if;
  foreach ch in array regexp_split_to_array(lower(q), '') loop
    cls := m ->> ch;
    if cls is not null then
      res := res || '[' || cls || ']';
    elsif ch ~ '^[!-/:-@\[-`{-~]$' then
      res := res || '\' || ch;                                  -- 英數以外的半形符號（例 % _ ( ) . \）當一般字元比對
    else
      res := res || ch;
    end if;
  end loop;
  return res;
end
$fn$;

-- 2) 日期排序鍵：跟 index.html 的 dateSortKey() 同規則，「2026/9/23」「2026-09-23」→「20260923」，看不懂的日期回傳 00000000
create or replace function public.wechat_date_key(s text)
returns text language sql immutable parallel safe as $fn$
  select coalesce(
    (select r.m[1] || lpad(r.m[2],2,'0') || lpad(r.m[3],2,'0')
       from regexp_match(coalesce(s,''), '(\d{4})\D+(\d{1,2})\D+(\d{1,2})') as r(m)),
    '00000000')
$fn$;

-- 3) 一組搜尋字 → 一組比對樣式（空白的略過；全部空白回傳 null＝不篩選）
create or replace function public.wechat_q_patterns(qs text[])
returns text[] language sql immutable parallel safe as $fn$
  select array_agg(public.wechat_q_pattern(q))
  from unnest(coalesce(qs, '{}'::text[])) as q
  where q is not null and q <> ''
$fn$;

-- 4) 主函式：微信訊息＋拜訪紀錄 合併後搜尋、排序、分頁
--    篩選條件之間是「全部都要符合」(AND)；同一個條件給多個關鍵字時是「符合任一個」(OR，給 AI 問答用)
--    各條件比對的欄位（跟改版前網頁 getFilteredUnifiedRows 完全相同）：
--      微信訊息  客戶=company；機型=model+raw；業務/聯絡人=sales+contact+raw；
--                關鍵字=company+contact+model+price+delivery+status+note+raw；日期=date
--      拜訪紀錄  客戶=customer；機型=model；業務/聯絡人=sales；
--                關鍵字=customer+sales+model+customer_info+competitor+market_info+other+work+work_purpose+next_action；日期=report_date
--    排序：日期新→舊；同一天微信訊息在前、拜訪紀錄在後；再依建立時間新→舊
--    欄位一律用 to_jsonb(整列)->>'欄位' 讀取：某欄位不存在時視為空白，不會讓函式出錯（例如微信訊息不一定有 contact 欄）
--    回傳 JSON：total（符合筆數）、wechat_count / visit_count（各類符合筆數）、
--               all_wechat / all_visit（看得到的總筆數；有指定 p_kind 時另一類為 0）、rows（這一頁的資料）
create or replace function public.wechat_customer_feed(
  p_company     text[]  default null,
  p_model       text[]  default null,
  p_person      text[]  default null,
  p_keyword     text[]  default null,
  p_from_key    text    default null,   -- 日期區間起，格式 YYYYMMDD（null＝不限）
  p_to_key      text    default null,   -- 日期區間訖，格式 YYYYMMDD（null＝不限）
  p_kind        text    default null,   -- 'wechat' / 'visit' / null＝兩種都要
  p_offset      int     default 0,
  p_limit       int     default 15,
  p_include_src boolean default false   -- true＝每筆附上原始整列資料（AI 問答需要報價/交期等欄位）
)
returns jsonb
language sql stable security invoker
set search_path = public
as $fn$
with base as materialized (  -- 每張表只掃一次（RLS 權限檢查很花時間），後面各步驟共用
  select 'wechat'::text as kind, 0 as kind_order, w.id::text as id, w.created_at,
         coalesce(j->>'date','') as date, coalesce(j->>'sales','') as sales,
         coalesce(j->>'company','') as customer, coalesce(j->>'model','') as model,
         coalesce(nullif(j->>'raw',''), nullif(j->>'note',''), '') as info,
         coalesce(j->>'other','') as other,
         coalesce(j->>'company','') as h_company,
         concat_ws(' ', coalesce(j->>'model',''), coalesce(j->>'raw','')) as h_model,
         concat_ws(' ', coalesce(j->>'sales',''), coalesce(j->>'contact',''), coalesce(j->>'raw','')) as h_person,
         concat_ws(' ', coalesce(j->>'company',''), coalesce(j->>'contact',''), coalesce(j->>'model',''), coalesce(j->>'price',''),
                        coalesce(j->>'delivery',''), coalesce(j->>'status',''), coalesce(j->>'note',''), coalesce(j->>'raw','')) as h_keyword,
         j as src
  from public.wechat_messages w cross join lateral (select to_jsonb(w) as j) x
  where p_kind is null or p_kind = 'wechat'
  union all
  select 'visit'::text, 1, v.id::text, v.created_at,
         coalesce(j->>'report_date',''), coalesce(j->>'sales',''),
         coalesce(j->>'customer',''), coalesce(j->>'model',''),
         concat_ws(E'\n\n', nullif(j->>'customer_info',''),
                   '【競爭對手】' || nullif(j->>'competitor',''),
                   '【市場訊息】' || nullif(j->>'market_info','')),
         concat_ws(E'\n\n', nullif(j->>'other',''),
                   '【陪同人員】' || nullif(j->>'companion','')),
         coalesce(j->>'customer',''),
         coalesce(j->>'model',''),
         coalesce(j->>'sales',''),
         concat_ws(' ', coalesce(j->>'customer',''), coalesce(j->>'sales',''), coalesce(j->>'model',''), coalesce(j->>'customer_info',''),
                        coalesce(j->>'competitor',''), coalesce(j->>'market_info',''), coalesce(j->>'other',''),
                        coalesce(j->>'work',''), coalesce(j->>'work_purpose',''), coalesce(j->>'next_action','')),
         j
  from public.visit_records v cross join lateral (select to_jsonb(v) as j) x
  where p_kind is null or p_kind = 'visit'
),
pats as materialized (  -- 搜尋字只轉換一次（materialized），不要每筆資料都重算
  select public.wechat_q_patterns(p_company) as pc, public.wechat_q_patterns(p_model) as pm,
         public.wechat_q_patterns(p_person) as pp, public.wechat_q_patterns(p_keyword) as pk
),
keyed as (
  select b.*, public.wechat_date_key(b.date) as date_key from base b
),
filtered as (
  select k.* from keyed k cross join pats
  where (pats.pc is null or k.h_company ~* any(pats.pc))
    and (pats.pm is null or k.h_model   ~* any(pats.pm))
    and (pats.pp is null or k.h_person  ~* any(pats.pp))
    and (pats.pk is null or k.h_keyword ~* any(pats.pk))
    and ( (p_from_key is null and p_to_key is null)
          or ( k.date_key <> '00000000'                       -- 日期看不懂的，篩日期區間時當作不符合（跟網頁原本一樣）
               and (p_from_key is null or k.date_key >= p_from_key)
               and (p_to_key   is null or k.date_key <= p_to_key) ) )
),
page as (
  select f.kind, f.id, f.date, f.sales, f.customer, f.model, f.info, f.other, f.created_at, f.date_key,
         case when p_include_src then f.src end as src, f.kind_order
  from filtered f
  order by f.date_key desc, f.kind_order, f.created_at desc, f.id
  limit least(greatest(coalesce(p_limit,15),1),1000) offset greatest(coalesce(p_offset,0),0)
)
select jsonb_build_object(
  'total',        (select count(*) from filtered),
  'wechat_count', (select count(*) from filtered where kind = 'wechat'),
  'visit_count',  (select count(*) from filtered where kind = 'visit'),
  -- 總筆數直接從 base 算，不再另外掃一次資料表（2026-10-16 實測：每掃一次拜訪紀錄約 2.5 秒，主要花在 RLS 權限檢查）
  'all_wechat',   (select count(*) from base where kind = 'wechat'),
  'all_visit',    (select count(*) from base where kind = 'visit'),
  'rows', coalesce((select jsonb_agg(to_jsonb(p) - 'kind_order' order by p.date_key desc, p.kind_order, p.created_at desc, p.id) from page p), '[]'::jsonb)
)
$fn$;

grant execute on function public.wechat_q_pattern(text) to authenticated;
grant execute on function public.wechat_q_patterns(text[]) to authenticated;
grant execute on function public.wechat_date_key(text) to authenticated;
grant execute on function public.wechat_customer_feed(text[], text[], text[], text[], text, text, text, int, int, boolean) to authenticated;
